#include <stdio.h>
#include <stdlib.h>

void countingSort(int arr[], int n) {
    // Find the maximum element to determine the range of counting array
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    // Create a counting array to store the count of each element
    size_t count_size = (size_t)(max + 1);
    if (count_size > SIZE_MAX / sizeof(int)) {
        fprintf(stderr, "Error: Memory allocation too large\n");
        return;
    }
    int* count = (int*)malloc(count_size * sizeof(int));
    if (count == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        return;
    }

    // Initialize the counting array
    for (int i = 0; i <= max; i++) {
        count[i] = 0;
    }

    // Count the occurrences of each element in the input array
    for (int i = 0; i < n; i++) {
        count[arr[i]]++;
    }

    // Modify the counting array to store the position of each element
    for (int i = 1; i <= max; i++) {
        count[i] += count[i - 1];
    }

    // Create a temporary array to store the sorted result
    size_t output_size = (size_t)n;
    if (output_size > SIZE_MAX / sizeof(int)) {
        fprintf(stderr, "Error: Memory allocation too large\n");
        free(count);
        return;
    }
    int* output = (int*)malloc(output_size * sizeof(int));
    if (output == NULL) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(count);
        return;
    }

    // Build the output array by placing elements in their correct positions
    for (int i = n - 1; i >= 0; i--) {
        output[count[arr[i]] - 1] = arr[i];
        count[arr[i]]--;
    }

    // Copy the sorted elements back to the original array
    for (int i = 0; i < n; i++) {
        arr[i] = output[i];
    }

    // Free allocated memory
    free(count);
    free(output);
}

int main() {
    int arr[] = {4, 2, 10, 8, 7, 1, 5, 6, 3, 9};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }

    countingSort(arr, n);

    printf("\nSorted array: ");
    for (int i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }

    return 0;
}

